import os, sys, base64, paramiko
for _s in (sys.stdout, sys.stderr):
    if hasattr(_s, 'reconfigure'): _s.reconfigure(encoding='utf-8', errors='replace')
KEY = os.path.expanduser('~/.ssh/trader_vps')
b = paramiko.SSHClient(); b.set_missing_host_key_policy(paramiko.AutoAddPolicy())
b.connect('87.107.152.67', 22, username='root', pkey=paramiko.Ed25519Key.from_private_key_file(KEY), timeout=25, look_for_keys=False, allow_agent=False)
BACKUP = base64.b64decode('').decode()
HEALTH = base64.b64decode('').decode()
def run(cmd, timeout=300, check=True, label='', stdin=None):
    print('B>> ' + label, flush=True)
    si, so, se = b.exec_command(cmd, timeout=timeout)
    if stdin: si.write(stdin); si.channel.shutdown_write()
    out = so.read().decode('utf-8','replace'); err = se.read().decode('utf-8','replace')
    code = so.channel.recv_exit_status()
    print(((out.strip()[:400]) + ((' E ' + err.strip()[:200]) if err.strip() else '')), flush=True)
    if check and code != 0: sys.exit(1)
    return out
def put(path, content, mode, label):
    sftp = b.open_sftp()
    with sftp.open(path, 'w') as f: f.write(content)
    run('chmod ' + mode + ' ' + path, label=label + '-chmod')
put('/usr/local/bin/umami-backup.sh', BACKUP + chr(10), '700', 'backup-script')
put('/usr/local/bin/umami-health.sh', HEALTH + chr(10), '700', 'health-script')
run('mkdir -p /var/backups/umami && bash /usr/local/bin/umami-backup.sh', label='backup-run')
run('/usr/local/bin/umami-health.sh', label='health-run')
timer = '[Unit]' + chr(10) + 'Description=Daily Umami analytics backup' + chr(10) + '[Timer]' + chr(10) + 'OnCalendar=*-*-* 02:30:00' + chr(10) + 'Persistent=true' + chr(10) + '[Install]' + chr(10) + 'WantedBy=timers.target' + chr(10)
svc = '[Unit]' + chr(10) + 'Description=Umami analytics backup' + chr(10) + '[Service]' + chr(10) + 'Type=oneshot' + chr(10) + 'ExecStart=/usr/local/bin/umami-backup.sh' + chr(10)
htimer = timer.replace('Daily Umami analytics backup', 'Hourly Umami health probe').replace('02:30:00', 'hourly')
put('/etc/systemd/system/umami-backup.timer', timer, '644', 'btimer')
put('/etc/systemd/system/umami-backup.service', svc, '644', 'bsvc')
put('/etc/systemd/system/umami-health.timer', htimer, '644', 'htimer')
run('systemctl daemon-reload && systemctl enable --now umami-backup.timer umami-health.timer && systemctl list-timers --no-pager | grep umami', label='timers-enable')
run('LATEST=$(ls -1t /var/backups/umami/umami-*.sql.gz | head -1); su - postgres -c "dropdb --if-exists umami_restore_drill"; su - postgres -c "createdb umami_restore_drill"; zcat $LATEST | su - postgres -c "psql -q umami_restore_drill" && su - postgres -c "psql -tA -d umami_restore_drill"', label='restore-drill', stdin="select 'drill_tables='||count(*) from information_schema.tables where table_schema='public';")
run('su - postgres -c "dropdb umami_restore_drill" && echo drill-cleaned', label='drill-cleanup')
run('systemctl show umami -p MemoryCurrent -p MemoryMax -p CPUQuotaPerSecUSec; systemctl show postgresql@16-main -p MemoryCurrent', label='resources')
run('for s in trader-vnext-predict trader-market trader-micro trader-watchdog trader-brain m23-opportunity-shadow; do printf "%s=%s " "$s" "$(systemctl is-active $s)"; done; echo; uptime', label='trader-health-after')
b.close()
print('B-SIDE BACKUP+HEALTH DONE', flush=True)